    # Normalize remove: sort and merge overlapping intervals
    remove_sorted = sorted(remove)
    merged_remove = []
    for start, end in remove_sorted:
        if merged_remove and start <= merged_remove[-1][1]:
            merged_remove[-1] = (merged_remove[-1][0], max(merged_remove[-1][1], end))
        else:
            merged_remove.append((start, end))

    result = []
    for b_start, b_end in base:
        current_start = b_start
        for r_start, r_end in merged_remove:
            if r_end <= current_start:
                continue
            if r_start >= b_end:
