from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union


def shift_weekly(entries: Iterable[Tuple[int, int, int]], offset: int) -> List[Tuple[int, int, int]]:
    """
    Shift recurring weekly entries (day, start, end) by `offset` minutes.
    """
    MINUTES_PER_DAY = 1440
    MINUTES_PER_WEEK = 7 * MINUTES_PER_DAY

    results: List[Tuple[int, int, int]] = []

    for day, start, end in entries:
        if not (0 <= day <= 6):
            raise ValueError(f"Invalid day: {day}")
        if not (0 <= start < MINUTES_PER_DAY):
            raise ValueError(f"Invalid start time: {start}")
        if end <= start:
            raise ValueError(f"End time must be greater than start time: {end} <= {start}")

        abs_start = day * MINUTES_PER_DAY + start
        abs_end = day * MINUTES_PER_DAY + end
        duration = abs_end - abs_start

        shifted_start = (abs_start + offset) % MINUTES_PER_WEEK
        shifted_end = shifted_start + duration

        if shifted_end > MINUTES_PER_WEEK:
            segments = [(shifted_start, MINUTES_PER_WEEK), (0, shifted_end % MINUTES_PER_WEEK)]
        else:
            segments = [(shifted_start, shifted_end)]

        for s, e in segments:
            curr = s
            while curr < e:
                next_midnight = ((curr // MINUTES_PER_DAY) + 1) * MINUTES_PER_DAY
                segment_end = min(e, next_midnight)

                day_idx = curr // MINUTES_PER_DAY
                start_in_day = curr % MINUTES_PER_DAY
                end_in_day = segment_end % MINUTES_PER_DAY

                # If segment_end is a midnight boundary, end_in_day is 0, but it should be 1440 for the segment
                if segment_end == next_midnight:
                    end_in_day = MINUTES_PER_DAY

                results.append((day_idx, start_in_day, end_in_day))
                curr = segment_end

    return sorted(results)
